interface Item {
  id: string;
  value: number;
}

// BUG: items.find() re-scans the WHOLE array for every id - O(n*m) overall
// and far too slow once both lists are large.
export function sumForIds(items: Item[], ids: string[]): number {
  let total = 0;
  for (const id of ids) {
    const found = items.find((it) => it.id === id);
    if (found) {
      total += found.value;
    }
  }
  return total;
}

