function assertEqual(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) {
    throw new Error(`${message}: expected ${expected}, got ${actual}`);
  }
}

import { sumForIds } from "./lookup";

// basic correctness
assertEqual(
  sumForIds([{ id: "a", value: 10 }, { id: "b", value: 20 }], ["a", "b", "z"]),
  30,
  "basic sum",
);

// duplicate ids: the FIRST occurrence must win (matches Array.find semantics)
assertEqual(
  sumForIds([{ id: "x", value: 1 }, { id: "x", value: 999 }], ["x"]),
  1,
  "duplicate id must resolve to the FIRST occurrence's value",
);

// empty inputs
assertEqual(sumForIds([], ["a"]), 0, "empty items");
assertEqual(sumForIds([{ id: "a", value: 5 }], []), 0, "empty ids");

// performance
{
  const n = 60000;
  const items = Array.from({ length: n }, (_, i) => ({ id: `id${i}`, value: i }));
  const ids = Array.from({ length: n }, (_, i) => `id${i}`);
  const expected = items.reduce((s, it) => s + it.value, 0);

  const start = Date.now();
  const got = sumForIds(items, ids);
  const elapsed = (Date.now() - start) / 1000;

  assertEqual(got, expected, "large-input sum");
  // calibrated: Array.find per id is ~3.7s on fast native hardware at
  // n=60000 and slower in the sandbox; a Map lookup is ~0.01s
  if (elapsed >= 1.5) {
    throw new Error(
      `sumForIds took ${elapsed.toFixed(2)}s for ${n} ids; expected a Map ` +
        `built once, not items.find() per id (O(n*m))`,
    );
  }
}

