interface Item {
  id: string;
  value: number;
}

export function sumForIds(items: Item[], ids: string[]): number {
  // FIRST occurrence wins for a duplicate id, matching what items.find()
  // would have returned.
  const byId = new Map<string, number>();
  for (const it of items) {
    if (!byId.has(it.id)) {
      byId.set(it.id, it.value);
    }
  }
  let total = 0;
  for (const id of ids) {
    const v = byId.get(id);
    if (v !== undefined) {
      total += v;
    }
  }
  return total;
}

